    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.4 * pressure;

    // Relative-to-mean coupling: consolidate toward tighter bins.
    score -= 0.9 * (bin_residual as f64 - mean_residual);

    // Late-stream: prefer minimal post_residual more aggressively.
    score += progress * pr * 0.3;

