        }
        if fitting_bins_count > 0 {
            let fresh_res = cap - item;
            if fresh_res < mean_residual * 1.1 {
                score += 48.0 * (1.0 - fresh_res / (mean_residual * 1.1).max(1.0));
            }
            if fresh_res > pr && fitting_bins_count > 2 {
                score += 22.0;
            }
            // Avoid opening a bin whose fresh residual would strand more
            // space than the best existing fit would.
            if fresh_res > pr * 1.5 {
                score += 15.0 * ((fresh_res / pr.max(1.0)) - 1.5).min(2.0);
            }
        }
    } else {
        // Residual-space discipline for open bins: reward leaving residuals
        // in the useful band for the upcoming item.
        if next_item_size > 0 && post_residual > 0 {
            let nr = next_item_size as f64;
            let band_lo = nr * 0.5;
            let band_hi = nr * 1.6;
            if pr >= band_lo && pr <= band_hi {
                score -= 28.0 * (1.0 - (pr - band_lo) / (band_hi - band_lo).max(1.0));
            } else if pr < band_lo && pr > 0.0 {
                score += 20.0 * (1.0 - pr / band_lo.max(1.0));
            }
        }
        // Mild dead-space variance control: avoid residuals far from the
        // running mean unless they are near-perfect fits.
        let dev = (pr - mean_residual).abs();
        if dev > mean_residual * 1.5 && pr > item * 2.0 {
            score += 13.0 * (dev / (mean_residual * 1.5).max(1.0) - 1.0).min(2.0);
        }
    }

    // Progress coupling: early conservative, late prefer tight closures.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual shaped by stream progress.
    // Early: mildly reward tight fits (low post_residual). Late: strongly reward them.
    let progress_shape = 1.0 + 2.0 * progress * progress;
    score -= progress_shape * (cap - pr) * 0.05;

    // Non-linear penalty on dead space: cubic-ish in normalized residual,
    // amplified as stream progresses (waste matters more later).
    score += norm_pr * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits smoothly in the post-residual,
    // reward this placement with a smooth quadratic affinity term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 3.0 * (1.0 - slack / cap).powi(2);
        } else {
            // Next item won't fit; penalize proportionally to overshoot, smoothly.
            let over = (nxt - pr) / cap;
            score += 4.0 * over * over * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into existing bins (mild, smooth).
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * norm_pr;

    // Deviation from mean residual: reward bins that keep residual near/below mean.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make an empty bin attractive only when the item is large
    // or when no tight option exists; penalize opening bins for small items late.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 8.0 * (1.0 - fill) * (0.5 + progress);
        if fitting_bins_count > 0 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: bucket dead space by magnitude.
    // Classes: 0 (perfect), 1 (tiny waste 1..=5), 2 (medium 6..=15),
    // 3 (large 16..=40), 4 (huge >40, still half the bin wasted).
    let waste_class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 5 { 1 }
        else if post_residual <= 15 { 2 }
        else if post_residual <= 40 { 3 }
        else { 4 };

    // Reward tight fits strongly (super-linear in class quality).
    score -= (4 - waste_class as i32) as f64 * 18.0;

    // Perfect fit bonus, stronger late in the stream.
    if post_residual == 0 {
        score -= 30.0 + 25.0 * progress;
    }

    // Lookahead chaining: if the next item exactly fills post_residual,
    // this bin becomes perfect after two placements — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a new residual: mild reward,
            // scaled by how much room remains for the item after.
            let chain_left = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_left as f64 / 20.0).max(0.0);
        } else {
            // Next item cannot use the residual: penalize proportionally
            // to how stranded the leftover space is.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Modulo-style harmonic penalty: residuals that are awkward multiples
    // relative to capacity (e.g. 33, 34, 49, 51) rarely chain well.
    let mod10 = post_residual % 10;
    if post_residual > 0 && mod10 >= 1 && mod10 <= 2 {
        score += 6.0; // sliver residuals are nearly dead space
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * fill;
    }

    // New-bin candidate (empty bin): make it attractive only when the fit
    // into existing bins is poor. Judge by waste class of this placement.
    if bin_residual == bin_capacity {
        let base = 12.0; // slight inherent preference for reusing bins
        // If placing here would leave lots of dead space in an existing bin,
        // a fresh bin is better: subtract more to win the comparison.
        score -= base + 30.0 * waste_class as f64;
        // Early in the stream, growing the pool is cheap and useful.
        score -= 10.0 * (1.0 - progress);
        // Few open bins relative to stream length: expansion is fine.
        score -= 4.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Existing bin: reward bins whose residual is far below the mean
        // (consolidating scarce space into fewer, tighter bins).
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Mild global pressure to keep total bins low when many are open.
    if open_bins_count > 0 {
        score += open_bins_count as f64 * 0.02;
    }

    score
}

