            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Modulo-style harmonic penalty: residuals that are awkward multiples
    // relative to capacity (e.g. 33, 34, 49, 51) rarely chain well.
    let mod10 = post_residual % 10;
    if post_residual > 0 && mod10 >= 1 && mod10 <= 2 {
        score += 6.0; // sliver residuals are nearly dead space
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * fill;
    }

    // New-bin candidate (empty bin): make it attractive only when the fit
    // into existing bins is poor. Judge by waste class of this placement.
    if bin_residual == bin_capacity {
        let base = 12.0; // slight inherent preference for reusing bins
        // If placing here would leave lots of dead space in an existing bin,
        // a fresh bin is better: subtract more to win the comparison.
        score -= base + 30.0 * waste_class as f64;
        // Early in the stream, growing the pool is cheap and useful.
        score -= 10.0 * (1.0 - progress);
        // Few open bins relative to stream length: expansion is fine.
        score -= 4.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Existing bin: reward bins whose residual is far below the mean
        // (consolidating scarce space into fewer, tighter bins).
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Mild global pressure to keep total bins low when many are open.
    if open_bins_count > 0 {
        score += open_bins_count as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (min size 1, but practically tiny gaps are waste).
    // Penalize gaps that are unusable for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 20.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over spreading; with few open bins, allow new bins more readily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (1.0 - progress);

    // Penalize leaving gaps that are far below the mean residual
    // (fragmentation) unless it's an exact fit.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / (mean_residual + 1.0);
        if gap_ratio < 0.5 {
            score += 8.0 * (0.5 - gap_ratio);
        }
    }

    // Mild penalty on new bins when plenty of bins are open and mean
    // residual is large (existing bins have room to consolidate).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (best-fit core with non-linear sharpening).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, this bin stays useful.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward when the next item nearly fills the remaining space.
        let gap = post_residual - next_item_size;
        score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Penalize leaving a sliver the known next item cannot use.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open (amortization pressure).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Exception: if existing residuals are all too fragmented (mean residual small),
        // opening a fresh bin is less bad.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Mild penalty for spreading waste across many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is far below the mean (they are the "tight" ones;
    // placing here consolidates waste and keeps large residuals flexible).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: waste after placement
    let mut score = pr;

    // Non-linear coupling: waste is penalized more as the stream progresses
    // (fewer chances to recover residual later), scaled quadratically.
    let progress_coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += progress_coupling;

    // Reward tight fits: smooth sigmoid-like reward around small residuals
    let tight = (-norm_pr * 6.0).exp() - 1.0; // ~0 for large residual, negative near 0
    score += tight * (1.0 + progress) * 4.0;

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 12.0 * (1.0 - gap / cap).max(0.0);
        } else {
            score += 4.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with below-mean residual (consolidate waste)
    score += (pr - mean_residual) * 0.3;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: penalize opening a new bin early, less so late
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify dead space by capacity fraction ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;   // 25
    let eighth = c / 8.0;    // 12.5
    let half = c / 2.0;      // 50

    // Dead space below 1/8 capacity is nearly unusable (min item can be 1 but typical
    // items are large): penalize tiny post_residuals strongly to prefer tight fits.
    if post_residual < eighth as u32 {
        score += (eighth - pr) * 3.0;
    } else if post_residual <= quarter as u32 {
        // Sweet spot: residual in (12.5, 25] can host small/medium future items.
        score -= quarter - pr; // reward smaller residual inside the sweet band
    } else if post_residual <= half as u32 {
        // Mid band: moderately useful, mild penalty proportional to size.
        score += (pr - quarter) * 0.25;
    } else {
        // Large leftover (> half capacity): we wasted a big bin; penalize.
        score += (pr - half) * 0.75;
    }

    // --- Integer-division thresholds: exact "harmonic" residuals (divisible classes) ---
    // Residuals that are exact multiples of common item sizes (10,20,25,50) are
    // statistically more likely to be filled later; reward them.
    let harmonic = |r: u32| -> f64 {
        for d in [10u32, 20, 25, 50] {
            if r != 0 && r % d == 0 {
                return 6.0;
            }
        }
        0.0
    };
    score -= harmonic(post_residual);

    // --- Lookahead coupling: if next item fits exactly into post_residual, big reward ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this residual at all: penalize proportionally.
            score += 4.0 * ((next_item_size - post_residual) as f64 / c);
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: keep fresh bins slightly unattractive unless
    // open bins are congested (low mean residual) or stream is early. ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / c; // low => bins nearly full
        // Prefer new bin when congestion is low (open bins are full-ish) or early stream.
        score -= 15.0 * congestion + 10.0 * (1.0 - progress);
        // But if the item fits a bin snugly elsewhere, that bin already wins via
        // the tight-fit bonus above; add a mild default penalty to the new bin.
        score += 5.0;
    }

    // --- Modulo coupling between item and residual: items that leave residuals in the
    // same residue class mod 10 as themselves tend to chain well (empirical). ---
    if post_residual % 10 == item_size % 10 && post_residual > 0 {
        score -= 3.0;
    }

    // --- Mild pressure against hoarding many open bins late in the stream ---
    if open_bins_count > 8 {
        score += 0.05 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size {
        // Unusable gap: penalize proportionally to how much of it is wasted.
        let dead = post_residual as f64;
        score += dead * 1.5;
        // Extra harsh penalty if the gap is tiny (nearly worthless).
        if post_residual < 10 {
            score += 20.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward keeping room for the lookahead item.
        score -= 8.0;
        if post_residual == next_item_size {
            // Perfect lookahead fit: strongly favored.
            score -= 15.0;
        }
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // and penalize opening new ones less (i.e., make existing bins more attractive).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // Candidate for a NEW bin: penalize more when many bins are open.
        score += 5.0 + pressure * 6.0;
    } else {
        // Existing bin: mild reward scaled by pressure.
        score -= pressure * 2.0;
    }

    // Prefer bins with below-average residual (denser bins) to consolidate waste.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    // Slight preference for exact fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: judge whether opening a fresh bin is attractive.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin: pay for the wasted capacity
        // plus a small fixed overhead so we only open when fits are poor.
        let mut new_bin_score = 100.0 + 8.0;
        // If the next item would fit perfectly after this placement, opening
        // a new bin is very attractive (reserve space for lookahead).
        if next_item_size > 0 && next_item_size <= item_size {
            let rem = bin_capacity - item_size;
            if rem == next_item_size {
                new_bin_score -= 60.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 10.0 * progress;
        // Many open bins: discourage opening more.
        new_bin_score += 1.5 * open_bins_count as f64;
        return new_bin_score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: this placement leaves exactly room for next item.
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            let diff = if post_residual > next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64
            };
            // Penalize deviation from perfect 2-step match, sharper when close.
            score -= 25.0 * (-diff / 12.0).exp();
            // Leaving too little room for the next item wastes the lookahead.
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // Last item: just fill tightly.
        score -= 20.0;
    }

    // Reward tight fills relative to mean residual of open bins.
    score -= 6.0 * (mean_residual - post_residual as f64).max(0.0) / 10.0;
    // Penalize creating dead space smaller than the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins that are already well-filled (small residual before placement).
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core with non-linear penalty for large dead space
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here; penalize leaving a residue smaller than any useful item
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation into existing bins
    if open_bins_count > 2 {
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
    }

    // New-bin candidate handling: empty bin starts with high baseline; open a new bin only
    // when existing bins would leave very poor fits or item is large relative to residuals
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in stream, opening bins is cheaper
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - t) * 20.0;
        // large items benefit from a fresh bin when mean residual is small
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins among fitting candidates
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Discard residual that can never host the smallest item
    if post_residual > 0 && post_residual < 5 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * coupling;

    // Tight fits are increasingly valuable as the stream progresses.
    let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
    score += 12.0 * tightness * (0.5 + progress);

    // Penalize leaving residual that no future item could likely use.
    let gap_penalty = (post_residual as f64 / 100.0).powi(3);
    score += 20.0 * gap_penalty * (1.0 + progress);

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / 100.0) * (1.0 - progress);
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) - (mean_residual / 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit: zero dead space is always ideal ---
    if post_residual == 0 {
        score -= 200.0;
        return score;
    }

    // --- Harmonic class of post_residual (modulo arithmetic on capacity fractions) ---
    let pr = post_residual;
    let class10 = pr % 10;
    if class10 == 0 {
        // post_residual lands on a multiple of 10: maximally reusable class
        score -= 25.0;
    } else if class10 == 5 {
        // half-class: still fairly reusable
        score -= 8.0;
    } else {
        // penalize odd dead space proportional to distance from harmonic class
        let dist = class10.min(10 - class10) as f64;
        score += 3.0 * dist;
    }

    // --- Integer-division thresholds: how many "half-capacity chunks" remain ---
    let half_chunks = pr / (bin_capacity / 2);
    if half_chunks >= 1 {
        score -= 10.0 * half_chunks as f64;
    }

    // --- Lookahead coupling: can this bin also host the next item? ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward slack that still accommodates the lookahead item,
            // scaled by how tightly it will fit
            let tightness = (pr - next_item_size) as f64;
            score -= 15.0 + 0.3 * next_item_size as f64 - 0.1 * tightness;
        } else {
            // dead space relative to the next item: penalize the gap
            let gap = (next_item_size - pr) as f64;
            score += 0.5 * gap;
        }
        // harmonic coupling: next item leaves a multiple-of-10 residual too
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        }
    }

    // --- Capacity-fraction fill level: reward nearly-full bins ---
    let fill_fraction = 1.0 - (pr as f64 / bin_capacity as f64);
    if fill_fraction > 0.75 {
        score -= 20.0 * fill_fraction;
    } else if fill_fraction < 0.25 {
        // barely-touched bin: discourage fragmenting it with a big item
        score += 10.0 * (0.25 - fill_fraction) * 4.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate: penalize opening a fresh bin when alternatives exist ---
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if the item would leave a harmonic residual in a new bin, soften slightly
        if pr % 10 == 0 {
            score -= 10.0;
        }
    }

    // --- Contextual scaling: late in the stream, consolidation matters more ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    // --- Deviation from mean residual: prefer bins below average residual (fuller) ---
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are worthless.
    if post_residual < 10 {
        score -= 40.0; // perfect or near-perfect fit
    } else if post_residual <= 20 {
        // unusable dead space for typical items (min size 10... but sizes 1..100 possible)
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward bins whose residual exactly matches the item (perfect closure).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // disfavor opening new ones.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 30.0 + pressure + mean_residual * 0.5;
    } else {
        score -= pressure * 0.5;
