        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 40.0;
        }
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 10.0;
        }
        // NEW: fresh-bin residual shape check — a fresh bin whose post-residual
        // can host the next item with slack under 8 is a strong two-item chain;
        // deepen the reward, but only when open-bin count is still modest so we
        // don't over-open early.
        if next_item_size > 0 && fresh_post >= next_item_size && fresh_post - next_item_size <= 8 && open_bins_count < 10 {
            score -= 12.0;
        }
    } else {
        score -= pressure * 0.5;
        score -= progress * 12.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= (open_bins_count.min(20)) as f64 * 0.8;
        }
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        // Graded residual-consumption reward.
        let consumed_frac = item_size as f64 / bin_capacity.max(1) as f64;
        score -= consumed_frac * 14.0;
        // NEW: dead-space targeting — when mean residual is already low
        // (bins nearly closed), any leftover gap that cannot host the next
        // item is pure waste; penalize proportionally to the stranded amount.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && mean_residual < 22.0 {
            score += (next_item_size - post_residual) as f64 * 0.45;
        }
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 7.0;
        }
    }

    // Tight-fit preference.
    score += (bin_residual as f64 - item_size as f64) * 0.12;

    // Prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Exact-fill anticipation.
    if post_residual > 0 && post_residual <= 4 {
        score -= 30.0;
    }

    // Mid-gap harmony.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    // Graded dead-space penalty under low mean residual.
    if post_residual > 0 && mean_residual < 18.0 && post_residual > 24 {
        score += (post_residual - 24).min(40) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small to be useful get penalized,
    // but exact/near-exact fits get strong rewards.
    if post_residual == 0 {
        score -= 165.0;
    } else if post_residual < 10 {
        score -= 48.0; // near-perfect closure
    } else if post_residual <= 22 {
        score += (22 - post_residual) as f64 * 3.4;
    } else if post_residual > bin_capacity / 2 {
        // Large leftover gaps are wasteful unless the next item needs them.
        if next_item_size == 0 || post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item,
    // penalize placements that strand the known next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            score -= 19.0 + (post_residual - next_item_size).min(30) as f64 * 0.3;
        } else {
            score += 42.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space ratio term: penalize residuals that are too small to host
    // any plausible future item, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 8 {
        score += 26.0; // sliver gap: nearly unusable
    } else if post_residual < 16 && next_item_size > post_residual {
        score += 9.0;
    }

    // Pair-fit lookahead — reward bins whose post-residual can host the next
    // item AND whose post-post residual stays small (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste <= 12 {
            score -= 15.0; // smooth chain: next item closes this bin nicely
        } else if chain_waste <= 20 {
            score -= 6.0; // graded extension of the chain reward
        }
    }

    // Fill-ratio reward — prefer placements that consume a large share
    // of the bin's current residual, independent of absolute gaps.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= fill_ratio * 21.0;
        if fill_ratio > 0.9 {
            score -= 10.0 * (fill_ratio - 0.9) * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 68.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering; bonus for filling existing bins.
    let pressure = open_bins_count as f64 * 2.0;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 32.0 + pressure + mean_residual * 0.58;
        // Late stream: avoid opening bins for small items.
        if item_size < 42 && progress > 0.45 {
            score += 72.0;
        }
        // If the next item is large and current item small, a fresh bin is valuable.
        if next_item_size > 60 && item_size <= 40 {
            score -= 55.0;
        }
        // If nothing fits anywhere except this fresh bin, it is unavoidable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Opening a bin early when mean residual is high wastes capacity.
        if progress > 0.6 && mean_residual > 30.0 {
            score += 28.0;
        }
        // Opening a fresh bin for a mid-size item is usually worse than
        // squeezing into an existing bin unless the item is near capacity/2.
        if item_size < bin_capacity / 4 && progress > 0.3 {
            score += 18.0;
        }
        // Fresh-bin chain planning: reward if the fresh bin's post-residual
        // exactly hosts the next item (perfect two-item chain).
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) == next_item_size {
            score -= 36.0;
        }
        // Waste-forecast for fresh bins — if the residual left after this
        // item is a "dead" sliver that no item of plausible size can use,
        // opening a fresh bin here strands capacity; penalize harder.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if fresh_post > 0 && fresh_post < 12 && progress > 0.25 {
            score += 24.0;
        }
        // If the fresh bin would end with a residual that cannot host the
        // next item but some open bin could host both, prefer the open bin.
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 15.0;
        }
        // Fresh-bin quality gate — grade the fresh bin by how well the
        // item fills it. A fresh bin opened for a small item strands most of
        // its capacity; a fresh bin opened for a near-half or larger item
        // starts life with usable structure.
        let fresh_fill = item_size as f64 / bin_capacity.max(1) as f64;
        if fresh_fill < 0.35 {
            score += (0.35 - fresh_fill) * 95.0;
        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 42.0;
        }
        // Harmonious fresh-bin residual sizes that commonly occur among
        // items are likely hostable later — reward moderately.
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 11.0;
        }
        // NEW: fresh-bin opening is more acceptable when the open-bin pool
        // is already dense — a new bin adds a clean "slot" rather than
        // compounding fragmented residual across many bins.
        if open_bins_count > 12 && fresh_fill > 0.4 {
            score -= 9.0;
        }
    } else {
        score -= pressure * 0.5;
        // Late in the stream, consolidate aggressively into existing bins.
        score -= progress * 12.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= (open_bins_count.min(20)) as f64 * 0.8;
        }
        // Dead-space recovery — when this placement leaves a residual that
        // is dead for the next item but another bin could still host the next
        // item, mildly penalize; if it keeps the next item hostable, reward.
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        // Graded residual-consumption reward — reward consuming a large
        // absolute share of the bin's remaining space, complementing the
        // fill-ratio term with an absolute-capacity view to fight dead space.
        let consumed_frac = item_size as f64 / bin_capacity.max(1) as f64;
        score -= consumed_frac * 15.0;
        // Penalize leaving residuals in the awkward 5..15 band when the
        // mean residual is already low — these gaps are the main dead-space
        // source in compacted streams.
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 8.0;
        }
        // NEW: dead-space ratio gate — when this placement strands a
        // residual that is less than half the next item's size and no other
        // bin could absorb the overflow, the gap is effectively lost; add a
        // graded penalty scaled by how much of the residual is stranded.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += ((next_item_size - post_residual) as f64) * 0.35;
        }
    }

    // Tight-fit preference: residual close to item size is better.
    score += (bin_residual as f64 - item_size as f64) * 0.12;

    // Prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Exact-fill anticipation — if this placement nearly empties the bin,
    // give a graded bonus instead of only the binary zero-residual reward.
    if post_residual > 0 && post_residual <= 4 {
        score -= 31.0;
    }

    // Mid-gap harmony — residuals in [16, 30) that can host the next
    // item exactly are ideal staging zones; reward graded by tightness.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    // Graded dead-space penalty based on residual variance pressure —
    // when the average residual is small (bins are nearly closed), any
    // leftover gap above the next item's size is increasingly wasteful.
    if post_residual > 0 && mean_residual < 18.0 && post_residual > 24 {
        score += (post_residual - 24).min(40) as f64 * 0.5;
    }

    // NEW: variance-aware dead-space surcharge — with low residual variance
    // the stream is well-compacted; large post-residuals then represent
    // outliers that will likely never close. Penalize proportionally.
    if post_residual > 30 && mean_residual < 14.0 {
        score += ((post_residual - 30).min(50)) as f64 * 0.25;
    }

    score
}

