        let relief = 9.0 * (1.0 - post_residual as f64 / cap);
        score += tight_bonus - relief.min(tight_bonus);
    } else {
        score -= 2.5 * dev;
    }

    // Last-chance bin: strongly favor the only fitting open bin.
    if bin_residual != bin_capacity {
        if fitting_bins_count == 1 {
            score -= 60.0;
        } else if fitting_bins_count == 2 {
            score -= 14.0;
        }
    }

    // Open-bin consolidation pressure late in the stream.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.0;
        score -= progress * 10.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= open_bins_count.min(20) as f64 * 0.7;
