        // Fresh-bin planning: reserve a new bin for a large next item.
        if next_item_size > 60 && item_size <= 40 {
            score -= 50.0;
        }
        // Fresh bin is unavoidable if nothing else fits.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Fresh-bin quality gate: grade by how well the item fills it.
        let fresh_fill = item_size as f64 / cap;
