        if fill_ratio > 0.9 {
            score -= 10.0 * (fill_ratio - 0.9) * 10.0;
        }
        // NEW: slack-band penalty — bins whose post-residual lands in the
        // awkward 6..14 dead zone waste space unless the next item uses it.
        if post_residual >= 6 && post_residual <= 14
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 8.0 - progress_early * 4.0;
        }
    }

    // Last-chance bin preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 * 2.0;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        score += 32.0 + pressure + mean_residual * 0.55;
        if item_size < 42 && progress > 0.45 {
            score += 70.0;
        }
        if next_item_size > 60 && item_size <= 40 {
            score -= 55.0;
