        score -= progress * 12.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= (open_bins_count.min(20)) as f64 * 0.8;
        }
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        let consumed_frac = item_size as f64 / bin_capacity.max(1) as f64;
        score -= consumed_frac * 14.0;
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 7.0;
        }
    }

    // Tight-fit preference.
    score += (bin_residual as f64 - item_size as f64) * 0.12;

    // Prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Exact-fill anticipation.
    if post_residual > 0 && post_residual <= 4 {
        score -= 30.0;
    }

    // Mid-gap harmony.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    // Graded dead-space penalty under low mean residual.
    if post_residual > 0 && mean_residual < 18.0 && post_residual > 24 {
        score += (post_residual - 24).min(40) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
