            } else if slack <= 12 {
                score -= 22.0;
            } else if slack <= 20 {
                score -= 8.0;
            }
        } else {
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Fill-ratio reward for open bins.
    if bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 20.0;
        if fill_ratio > 0.9 {
            score -= (fill_ratio - 0.9) * 100.0;
        }
