        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Tighter-than-average preference.
    score += (mean_residual - bin_residual as f64) * 0.06;
    score += (bin_residual as f64 - item_size as f64) * 0.12;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 15.0;
    }

