    // but exact/near-exact fits get strong rewards.
    if post_residual == 0 {
        score -= 160.0;
    } else if post_residual < 10 {
        score -= 45.0; // near-perfect closure
    } else if post_residual <= 22 {
        score += (22 - post_residual) as f64 * 3.2;
    } else if post_residual > bin_capacity / 2 {
        // Large leftover gaps are wasteful unless the next item needs them.
        if next_item_size == 0 || post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item,
    // penalize placements that strand the known next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            // Proportional reward: slack exactly matching next item is ideal.
            score -= 18.0 + (post_residual - next_item_size).min(30) as f64 * 0.3;
        } else {
            score += 42.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space ratio term: penalize residuals that are too small to host
    // any plausible future item, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 8 {
        score += 25.0; // sliver gap: nearly unusable
    } else if post_residual < 16 && next_item_size > post_residual {
        score += 9.0;
    }

    // Pair-fit lookahead — reward bins whose post-residual can host the next
    // item AND whose post-post residual stays small (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste <= 12 {
            score -= 14.0; // smooth chain: next item closes this bin nicely
        } else if chain_waste <= 20 {
            score -= 6.0; // graded extension of the chain reward
        }
    }

    // Fill-ratio reward — prefer placements that consume a large share
    // of the bin's current residual, independent of absolute gaps.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= fill_ratio * 20.0;
        if fill_ratio > 0.9 {
            score -= 10.0 * (fill_ratio - 0.9) * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering; bonus for filling existing bins.
    let pressure = open_bins_count as f64 * 2.0;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 32.0 + pressure + mean_residual * 0.55;
        // Late stream: avoid opening bins for small items.
        if item_size < 42 && progress > 0.45 {
            score += 70.0;
        }
        // If the next item is large and current item small, a fresh bin is valuable.
        if next_item_size > 60 && item_size <= 40 {
            score -= 55.0;
        }
        // If nothing fits anywhere except this fresh bin, it is unavoidable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Opening a bin early when mean residual is high wastes capacity.
        if progress > 0.6 && mean_residual > 30.0 {
            score += 28.0;
        }
        // Opening a fresh bin for a mid-size item is usually worse than
        // squeezing into an existing bin unless the item is near capacity/2.
        if item_size < bin_capacity / 4 && progress > 0.3 {
            score += 18.0;
        }
        // Fresh-bin chain planning: reward if the fresh bin's post-residual
        // exactly hosts the next item (perfect two-item chain).
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) == next_item_size {
            score -= 35.0;
