        // Waste-forecast for fresh bins — if the residual left after this
        // item is a "dead" sliver that no item of plausible size can use,
        // opening a fresh bin here strands capacity; penalize harder.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if fresh_post > 0 && fresh_post < 12 && progress > 0.25 {
            score += 22.0;
        }
        // If the fresh bin would end with a residual that cannot host the
        // next item but some open bin could host both, prefer the open bin.
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 15.0;
        }
        // Fresh-bin quality gate — grade the fresh bin by how well the
        // item fills it. A fresh bin opened for a small item strands most of
        // its capacity; a fresh bin opened for a near-half or larger item
        // starts life with usable structure.
        let fresh_fill = item_size as f64 / bin_capacity.max(1) as f64;
        if fresh_fill < 0.35 {
            score += (0.35 - fresh_fill) * 90.0;
        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 40.0;
