        // When the fresh bin's post-residual is a "harmonious" size that
        // commonly occurs among items (mid-range residual likely hostable),
        // opening is less wasteful — reward moderately.
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 10.0;
        }
        // NEW: two-item exact-chain gate — opening a fresh bin is most
        // attractive when the item plus the next item nearly close it.
        // Grade the combined fill of the projected two-item bin and reward
        // tight chains, penalize loose ones.
        if next_item_size > 0 {
            let two_fill = (item_size + next_item_size) as f64 / bin_capacity.max(1) as f64;
            if two_fill > 0.9 {
                score -= 20.0 + (two_fill - 0.9) * 120.0;
            } else if two_fill < 0.55 {
                score += (0.55 - two_fill) * 35.0;
            }
