        // Dead-space recovery — when this placement leaves a residual that
        // is dead for the next item but another bin could still host the next
        // item, mildly penalize; if it keeps the next item hostable, reward.
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        // Graded residual-consumption reward — reward consuming a large
        // absolute share of the bin's remaining space, complementing the
        // fill-ratio term with an absolute-capacity view to fight dead space.
        let consumed_frac = item_size as f64 / bin_capacity.max(1) as f64;
        score -= consumed_frac * 14.0;
        // NEW: sharpen the awkward-residual penalty — gaps in the 5..15 band
        // are the main dead-space source; scale the penalty by how tight the
        // stream already is (low mean residual) and by progress.
        if post_residual > 4 && post_residual < 15 {
            let band_penalty = 7.0 + (15 - post_residual) as f64 * 0.6;
            score += band_penalty * (1.0 + (20.0 - mean_residual).max(0.0) / 40.0) * (0.6 + progress);
        }
        // NEW: perfect next-item closure anticipation — if the residual left
        // by this placement would be exactly consumed by the next item,
        // treat it as a near-closure and reward strongly (graded).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 22.0;
