            && post_residual - next_item_size <= 4 {
            score -= 10.0;
        }
    }

    // Tight-fit preference: residual close to item size is better.
    score += (bin_residual as f64 - item_size as f64) * 0.12;

    // Prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Exact-fill anticipation — if this placement nearly empties the bin,
    // give a graded bonus instead of only the binary zero-residual reward.
    if post_residual > 0 && post_residual <= 4 {
        score -= 30.0;
    }

    // Mid-gap harmony — residuals in [16, 30) that can host the next
    // item exactly are ideal staging zones; reward graded by tightness.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    // Graded dead-space penalty based on residual variance pressure —
    // when the average residual is small (bins are nearly closed), any
    // leftover gap above the next item's size is increasingly wasteful.
    if post_residual > 0 && mean_residual < 18.0 && post_residual > 24 {
        score += (post_residual - 24).min(40) as f64 * 0.5;
    }

    // NEW: global dead-space audit — residual waste measured against the
    // mean residual: bins holding far more slack than average are hoarding
    // capacity; nudge selection toward tighter bins late in the stream.
    if bin_residual != bin_capacity && progress > 0.35 {
        let excess = (bin_residual as f64 - mean_residual).max(0.0);
        score += excess * 0.04 * (progress - 0.35) * 3.0;
    }

    score
}

