    if progress > 0.85 && bin_residual != bin_capacity && fitting_bins_count > 0 {
        score -= 9.0;
    } else if progress > 0.85 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0;
    }

    score
}

