            score += 23.0;
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 16.0;
        }
        // Hostable mid-band fresh residuals.
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 13.0;
        }
        // Avoid opening fresh bins when open bins can host next item too.
        if fitting_bins_count >= 3 {
            score += 12.0 + fitting_bins_count.min(8) as f64 * 1.5;
        }
        // Late-stream consolidation.
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Open fresh only when fresh residual would host the next item well.
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_post > 0 && fresh_post >= next_item_size {
            let slack = fresh_post - next_item_size;
            if slack == 0 {
                score -= 24.0;
            } else if slack <= 6 {
                score -= 16.0;
            } else {
                score += slack.min(40) as f64 * 0.38;
            }
        }
        // Two-step fresh-bin planning.
        if next_item_size > 0 && fresh_post >= next_item_size {
            let after_next = fresh_post - next_item_size;
            if after_next > 0 && after_next <= 6 {
                score -= 11.0;
            }
        }
        // Discourage fresh bins whose residual lands just below the next item.
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size
            && next_item_size - fresh_post <= 15 {
            score += 13.0;
        }
        // Refinement: large items nearly filling a fresh bin are excellent anchors.
        if fresh_fill > 0.85 {
            score -= 18.0 * (fresh_fill - 0.85);
        }
    } else {
        score -= pressure * 0.5;
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
        if fitting_bins_count > 2 && post_residual > 0 && post_residual < 30 {
            score -= 4.0;
        }
        // Protect bins whose post-residual can host a large next item.
        if next_item_size > 55 && post_residual >= next_item_size {
            score -= 11.0;
        }
        if post_residual == 0 && next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight-fit and below-mean-residual preferences.
    score += (bin_residual as f64 - item_size as f64) * 0.12;
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Mid-gap harmony staging zone.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;

    // Graded exact/near-exact fit rewards.
    if post_residual == 0 {
        score -= 175.0;
    } else if post_residual <= 4 {
        score -= 34.0;
    } else if post_residual < 10 {
        score -= 21.0;
    } else if post_residual <= 22 {
        score += (22 - post_residual) as f64 * 3.4;
    }

    // Dead-space avoidance for unusable slivers.
    if post_residual > 0 && post_residual < 8 {
        score += 34.0;
    } else if post_residual > 0 && post_residual < 16 && next_item_size > post_residual {
        score += 14.0;
    }
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += (next_item_size - post_residual).min(30) as f64 * 0.5;
    }

    // Two-step lookahead: reward chains that host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste == 0 {
                score -= 74.0;
            } else if chain_waste <= 12 {
                score -= 21.0;
            } else if chain_waste <= 20 {
                score -= 9.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 42.0 + (next_item_size - post_residual) as f64;
        }
    } else if next_item_size == 0 {
        score -= 5.0;
    }

    // Fill-ratio rewards for real open bins.
    if bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 22.0;
        if fill_ratio > 0.9 {
            score -= (fill_ratio - 0.9) * 115.0;
        }
        score -= (item_size as f64 / cap) * 15.0;
        score -= progress * 13.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= open_bins_count.min(20) as f64 * 0.9;
        }
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 7.0;
        }
        if post_residual > 24 && mean_residual < 18.0 {
            score += (post_residual - 24).min(40) as f64 * 0.5;
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= (60 - post_residual) as f64 * 0.35;
        }
        if post_residual > 0 && post_residual < 10 && next_item_size >= 10 {
            score += 9.0;
        }
        if post_residual > 12 && post_residual < 20 && next_item_size > post_residual + 12 {
            score += 6.0;
        }
    }

    // Last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 78.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 17.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 * 2.0;

    if bin_residual == bin_capacity {
        score += 33.0 + pressure + mean_residual * 0.58;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
        if item_size < 42 && progress > 0.45 {
            score += 72.0;
        }
        if next_item_size > 60 && item_size <= 40 {
            score -= 58.0;
        }
        if fitting_bins_count == 0 {
            score -= 105.0;
        }
        if progress > 0.6 && mean_residual > 30.0 {
            score += 29.0;
        }
        if item_size < bin_capacity / 4 && progress > 0.3 {
            score += 19.0;
        }
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if next_item_size > 0 && fresh_post == next_item_size {
            score -= 44.0;
        }
        let fresh_fill = item_size as f64 / cap;
        if fresh_fill < 0.42 {
            score += (0.42 - fresh_fill) * 112.0;
        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 46.0;
        }
        if fresh_post > 0 && fresh_post < 12 && progress > 0.25 {
            score += 23.0;
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 16.0;
        }
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 13.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0 + fitting_bins_count.min(8) as f64 * 1.5;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_post > 0 && fresh_post >= next_item_size {
            let slack = fresh_post - next_item_size;
            if slack == 0 {
                score -= 24.0;
            } else if slack <= 6 {
                score -= 16.0;
            } else {
                score += slack.min(40) as f64 * 0.38;
            }
        }
        if next_item_size > 0 && fresh_post >= next_item_size {
            let after_next = fresh_post - next_item_size;
            if after_next > 0 && after_next <= 6 {
                score -= 11.0;
            }
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size
            && next_item_size - fresh_post <= 15 {
            score += 13.0;
        }
    } else {
        score -= pressure * 0.5;
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
        if fitting_bins_count > 2 && post_residual > 0 && post_residual < 30 {
            score -= 4.0;
        }
        if next_item_size > 55 && post_residual >= next_item_size {
            score -= 11.0;
        }
        if post_residual == 0 && next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight-fit and below-mean-residual preferences.
    score += (bin_residual as f64 - item_size as f64) * 0.12;
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Mid-gap harmony staging zone.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    // MUTATION: reserve bins with large residuals for genuinely large upcoming items.
    // If the next item is big and this open bin's post-residual could still host it,
    // but the current item barely fits here, prefer a tighter alternative.
    if bin_residual != bin_capacity && next_item_size > 45 && post_residual > 0 {
        let waste_now = post_residual;
        if waste_now < next_item_size && waste_now < 15 {
            score += 18.0;
        }
    }

    // MUTATION: late-stream, strongly prefer zero-waste placements anywhere.
    if progress > 0.7 && post_residual == 0 {
        score -= 25.0;
    }

    // MUTATION: penalize opening fresh bins late when the item could fit an open bin
    // with less than 10% waste.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.4 {
        let best_possible = fitting_bins_count;
        if best_possible > 0 && item_size as f64 / cap < 0.25 {
            score += 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, penalize wasted space more strongly.
    let progress_penalty = 1.0 + progress * progress * (pr / cap);
    score *= progress_penalty;

    // Smooth interaction: small post_residual is extra valuable when it leaves
    // room for the next item (reward), decaying quadratically with mismatch.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let match_reward = -6.0 * (-gap * gap / (cap * cap * 0.05)).exp() * (1.0 - progress * 0.5);
        score += match_reward;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Penalize bins that deviate from the mean residual (keeps pool balanced),
    // scaled smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // New-bin candidate: keep it neutral-ish; only attractive when item is
    // large relative to all residuals (smooth logistic gate).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = pr as f64 + 5.0 * (1.0 / (1.0 + (-8.0 * (fill - 0.6)).exp()));
    }

    score
}

