pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth;           // 0..=8 integer class
    let next_class = next_item_size / eighth;          // harmonic class of lookahead item

    // Reward when the next item lands exactly in the same harmonic class as post_residual
    // (perfect modular fit => near-zero future dead space).
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_class == post_class {
            score -= 12.0;
        } else if next_item_size <= post_residual / 2 {
            score -= 6.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize by how dead the space is.
        score += 4.0 + (post_residual as f64) * 0.05;
    }

    // Penalize residuals that fall into "awkward" modular classes (small, hard-to-fill slivers).
    let awkward = |r: u32| -> f64 {
        if r == 0 { 0.0 }
        else if r < eighth { 10.0 }        // tiny sliver: dead space
        else if r % quarter < eighth { 3.0 } // just past a quarter boundary
        else { 0.0 }
    };
    score += awkward(post_residual);

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when current bins are crowded
    // or the item would leave a bad class in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 - 10.0 * progress - 0.1 * open_bins_count as f64;
        if item_size % quarter == 0 {
            score -= 5.0; // big modular item: fresh bin packs it cleanly
        }
    }

    // Mild tie-break: prefer bins whose residual is closest to the mean (balance classes).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.02;

    score
}

