        // Exact 2-step match: next item fills this bin exactly.
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Next item fits into the post residual: reward, scaled by tightness.
        if next_item_size <= post_residual {
            let tight = 1.0 - (pr - nx) / bin_capacity as f64;
            score -= 100.0 + 50.0 * tight;
        } else {
            // Next item won't fit: penalize leaving dead space.
            score += 30.0 + 0.5 * (nx - pr);
        }
    }

    // Compare post residual against mean residual of open bins.
    let cap = bin_capacity as f64;
    let norm_pr = post_residual as f64 / cap;
    let norm_mean = mean_residual / cap;
    score += 20.0 * (norm_pr - norm_mean);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 50.0 + 5.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere, new bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score -= 80.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
