    if post_residual == 0 {
        score -= 175.0;
    } else if post_residual <= 4 {
        score -= 34.0;
    } else if post_residual < 10 {
        score -= 21.0;
    } else if post_residual <= 22 {
        score += (22 - post_residual) as f64 * 3.4;
