    // Dead-space avoidance for unusable slivers (tightened band).
    if post_residual > 0 && post_residual < 8 {
        score += 34.0;
    } else if post_residual > 0 && post_residual < 16 && next_item_size > post_residual {
        score += 14.0;
    }
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += (next_item_size - post_residual).min(30) as f64 * 0.5;
    }
    // NEW: sliver-band awareness — residuals of 1..=3 are nearly dead unless the
    // very next item is tiny; penalize proportionally to how stranded they are.
    if post_residual >= 1 && post_residual <= 3 {
        if next_item_size > post_residual {
            score += 6.0 + (next_item_size - post_residual).min(20) as f64 * 0.4;
        } else {
            score -= 5.0;
        }
    }

    // Two-step lookahead: reward chains that host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste == 0 {
                score -= 74.0;
            } else if chain_waste <= 12 {
                score -= 21.0;
            } else if chain_waste <= 20 {
                score -= 9.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 42.0 + (next_item_size - post_residual) as f64;
        }
    } else if next_item_size == 0 {
        score -= 5.0;
    }

    // Fill-ratio rewards for real open bins.
    if bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 22.0;
        if fill_ratio > 0.9 {
            score -= (fill_ratio - 0.9) * 115.0;
        }
        score -= (item_size as f64 / cap) * 15.0;
        score -= progress * 13.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= open_bins_count.min(20) as f64 * 0.9;
        }
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 7.0;
        }
        if post_residual > 24 && mean_residual < 18.0 {
            score += (post_residual - 24).min(40) as f64 * 0.5;
        }
        // Prefer bins whose leftover stays "usable".
        if post_residual >= 25 && post_residual <= 60 {
            score -= (60 - post_residual) as f64 * 0.35;
        }
        // Penalize residuals stranded just below a common small-item band.
        if post_residual > 0 && post_residual < 10 && next_item_size >= 10 {
            score += 9.0;
        }
        // Penalize awkward gaps that can't host a mid-size follow-up.
        if post_residual > 12 && post_residual < 20 && next_item_size > post_residual + 12 {
            score += 6.0;
        }
        // NEW: dead-space ratio term — prefer placements that leave a residual
        // which is a plausible host for any future item (not just the next one).
        if post_residual > 0 && post_residual < 100 {
