    let mut score = post_residual as f64;

    // Progress in the stream (0..1), used to anneal exploration vs. exploitation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual < 10 {
        score += 6.0; // unusable sliver
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        // Residual can't hold the lookahead item: mild penalty, worse late in stream.
        score += 2.0 + 3.0 * progress;
    }

    // Lookahead reward: if the next item fits exactly/well into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        }
        // Perfect pair: item + next fill the bin completely.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over
    // opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize drawing down bins whose residual is close to the global mean
    // when many bins are open: keeps residual distribution balanced.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * spread * (open_bins_count as f64).sqrt();

    // Early in the stream, encourage consolidation into few bins; later,
    // allow opening new bins when existing fits are poor.
    let consolidation = 1.0 - progress;
    score += consolidation * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // New-bin candidate: neutral-ish baseline. Choose it only when the best
    // existing fit would leave a lot of awkward residual.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count > 0 {
