pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    let mut dead_penalty = 0.0;
    if post > 0 {
        // Modulo classes on post_residual relative to capacity fractions.
        let m = post % quarter.max(1);
        dead_penalty += (m as f64) * 0.05;
        // Dead space too small to hold the smallest plausible item (<= 10 or next_item_size).
        let min_useful = next_item_size.min(10).max(1);
        if post < min_useful {
            dead_penalty += 25.0; // unusable residual: wasted capacity
        } else if post < quarter {
            dead_penalty += 8.0; // awkward small class
        } else if post < half {
            dead_penalty += 2.0; // moderate class
        } else {
            dead_penalty -= 6.0; // large residual: versatile
        }
        // Integer-division threshold: can post_residual hold the lookahead item?
        if next_item_size > 0 && post >= next_item_size {
            score -= 12.0; // chain-friendly: next item fits here too
        } else if next_item_size > 0 {
            score += 4.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer denser bins when many bins are open (reduce bin sprawl).
    if open_bins_count > 1 {
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln() * 3.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmented outliers)
    // except when they are near-perfect fits.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if fit_ratio < 0.95 {
        score += dev * 0.02;
    }

    // Early stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress * 5.0);
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else {
            // Opening a new bin wastes the residual of existing bins; penalize
            // proportionally to how much slack exists, unless the best existing
            // fit would be terrible.
            score += 20.0 + mean_residual * 0.15;
        }
    }

    score += dead_penalty;
    score
}

