        if post_residual > 0 && post_residual < 10 && next_item_size >= 10 {
            score += 9.0;
        }
        if post_residual > 12 && post_residual < 20 && next_item_size > post_residual + 12 {
            score += 6.0;
        }
        // Residual-entropy coupling: bins far below mean residual absorb slack well.
        if (bin_residual as f64) < mean_residual * 0.6 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 78.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 17.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 * 2.0;

    if bin_residual == bin_capacity {
        score += 33.0 + pressure + mean_residual * 0.58;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
        if item_size < 42 && progress > 0.45 {
            score += 72.0;
        }
        if next_item_size > 60 && item_size <= 40 {
            score -= 58.0;
        }
        if fitting_bins_count == 0 {
            score -= 105.0;
        }
        if progress > 0.6 && mean_residual > 30.0 {
            score += 29.0;
        }
        if item_size < bin_capacity / 4 && progress > 0.3 {
            score += 19.0;
        }
        // Fresh-bin chain planning: perfect two-item chain.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if next_item_size > 0 && fresh_post == next_item_size {
            score -= 44.0;
        }
        // Fresh-bin quality gate by fill fraction (slightly stricter late).
        let fresh_fill = item_size as f64 / cap;
        let gate = if progress > 0.55 { 0.45 } else { 0.42 };
        if fresh_fill < gate {
