        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 46.0;
        }
        if fresh_post > 0 && fresh_post < 12 && progress > 0.25 {
            score += 23.0;
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 16.0;
        }
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 13.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0 + fitting_bins_count.min(8) as f64 * 1.5;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_post > 0 && fresh_post >= next_item_size {
            let slack = fresh_post - next_item_size;
            if slack == 0 {
                score -= 24.0;
            } else if slack <= 6 {
                score -= 16.0;
            } else {
                score += slack.min(40) as f64 * 0.38;
            }
        }
        if next_item_size > 0 && fresh_post >= next_item_size {
            let after_next = fresh_post - next_item_size;
            if after_next > 0 && after_next <= 6 {
                score -= 11.0;
            }
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size
            && next_item_size - fresh_post <= 15 {
            score += 13.0;
        }
        // Dead-space guard: don't open fresh bins that strand tiny unusable gaps.
        if fresh_post > 0 && fresh_post < 5 {
            score += 18.0;
        }
    } else {
        score -= pressure * 0.5;
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
        if fitting_bins_count > 2 && post_residual > 0 && post_residual < 30 {
            score -= 4.0;
        }
        if next_item_size > 55 && post_residual >= next_item_size {
            score -= 11.0;
        }
        if post_residual == 0 && next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight-fit and below-mean-residual preferences.
    score += (bin_residual as f64 - item_size as f64) * 0.12;
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Mid-gap harmony staging zone.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are fine,
    // but gaps below typical small-item sizes are "unusable" waste.
    // Penalize gaps in (0, 15] heavily unless zero.
    if post_residual > 0 && post_residual <= 15 {
        score += 30.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual > 15 && post_residual <= 30 {
        score += 8.0;
