    if post_residual <= 3 {
        score -= 40.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0; // next item won't fit here; dead end likely
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 5.0 + 3.0 * open_bins_count as f64;
