        if next_item_size > 55 && post_residual >= next_item_size {
            score -= 11.0;
        }
        if post_residual == 0 && next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0;
        }
        // NEW: favor bins that stay near-empty late in the stream so they
        // remain flexible for large arrivals.
        if progress > 0.7 && bin_residual > bin_capacity / 2 && item_size < 30 {
