pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate exploration.
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // ---- Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // ---- Dead-space penalty: leftover space that is too small to be useful later.
    // Residuals below the minimum plausible item size are near-worthless.
    let pr = post_residual as f64;
    if pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    } else if pr < 20.0 {
        score += 8.0 * (20.0 - pr) / 10.0;
    }

    // ---- Lookahead coupling: reward leaving exactly enough room for the next item,
    // penalize leaving a gap that neither fits the next item nor is comfortably large.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // The next item can still land here: good, but only mildly.
            let slack = pr - ni;
            score -= 6.0;
            // Perfect chain fit (next item exactly fills what remains afterwards)
            if slack < 1.0 {
                score -= 10.0;
            } else if slack < 10.0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here after placement: penalize proportionally
            // to how "stranded" the leftover space is.
            let stranded = ni - pr;
            score += 3.0 + 0.15 * stranded;
        }
    } else {
        // Last item: pure tight fit is all that matters.
        score -= 5.0 * fill_ratio;
    }

    // ---- Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count >= 2 {
        // Many candidates: be pickier about tightness, discourage mediocre fits
        // so a better bin (or a fresh bin) can win.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * (1.0 - fill_ratio);
    }

    // ---- Global state coupling: when the fleet of open bins is already fragmented
    // (high mean residual relative to capacity), prefer consolidating into existing bins.
    let frag = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * frag;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full residual; make it slightly worse than a
        // decent existing fit, but better than a terrible one.
        score += 4.0;
        // Early in the stream, exploring new bins is cheap and informative.
        let explore = (1.0 - progress).powf(1.5);
        score -= 10.0 * explore;
        // If many bins are open and fragmented, avoid adding more.
        score += 0.6 * open_bins_count as f64 * frag;
        // If the item is huge relative to capacity, a fresh bin is a natural home.
        score -= 4.0 * (item_size as f64 / bin_capacity as f64);
        // If nothing else fits well (this bin is one of few candidates), new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    // ---- Time-horizon modulation: late in the stream, be conservative —
    // avoid opening bins and squeeze existing ones harder.
    score += 6.0 * progress * (1.0 - fill_ratio);

    // Small deterministic tie-breaker favoring emptier bins slightly.
    score += 0.01 * (bin_residual as f64 / bin_capacity as f64);

    score
}

