    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: tight fits (small post_residual) rewarded super-linearly.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible next item can use; smooth quadratic in post_residual.
    let usable = if next_item_size > 0 && (next_item_size as f64) <= post { 1.0 } else { 0.0 };
    score += (1.0 - usable) * 0.15 * post * post / cap;

    // Reward bins whose residual will be consumed by the lookahead item.
    if usable > 0.0 {
        score -= 12.0 * (1.0 - (post - next_item_size as f64) / cap);
    }

    // Stream-progress coupling: later in the stream, consolidate more aggressively.
    score -= 10.0 * progress * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Many open bins: penalize spreading; favor filling existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Mean-residual coupling: if this bin is far from the mean residual, slight penalty.
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new = bin_residual == bin_capacity && item_size > 0;
    if is_new {
        score = cap - item_size as f64 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

