    if post_residual > 0 && post_residual < 9 {
        score += post_residual as f64 * (0.8 + progress * 1.6);
    }

    // Two-step lookahead: reward chains that host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste == 0 {
                score -= 74.0;
            } else if chain_waste <= 12 {
                score -= 21.0;
            } else if chain_waste <= 20 {
                score -= 9.0;
            } else {
                score -= 3.0;
            }
            // NEW: reward keeping residuals in the "hostable next time" band.
            if chain_waste > 0 && chain_waste <= 25 && next_item_size >= 15 {
                score -= (25 - chain_waste) as f64 * 0.3;
            }
        } else {
            score += 42.0 + (next_item_size - post_residual) as f64;
        }
    } else if next_item_size == 0 {
        score -= 5.0;
    }

    // Fill-ratio rewards for real open bins.
    if bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 22.0;
        if fill_ratio > 0.9 {
            score -= (fill_ratio - 0.9) * 115.0;
        }
        score -= (item_size as f64 / cap) * 15.0;
        score -= progress * 13.0;
        if progress > 0.5 && open_bins_count > 8 {
            score -= open_bins_count.min(20) as f64 * 0.9;
        }
        if post_residual > 4 && post_residual < 15 && mean_residual < 20.0 {
            score += 7.0;
        }
        if post_residual > 24 && mean_residual < 18.0 {
            score += (post_residual - 24).min(40) as f64 * 0.5;
        }
        // Prefer bins whose leftover stays "usable".
        if post_residual >= 25 && post_residual <= 60 {
            score -= (60 - post_residual) as f64 * 0.35;
        }
        // NEW: sweet-spot band for hosting typical mid items (30–70).
        if post_residual >= 30 && post_residual <= 70 {
            score -= 4.0;
        }
        // Penalize residuals stranded just below a common small-item band.
        if post_residual > 0 && post_residual < 10 && next_item_size >= 10 {
            score += 9.0;
        }
        // Penalize awkward gaps that can't host a mid-size follow-up.
        if post_residual > 12 && post_residual < 20 && next_item_size > post_residual + 12 {
            score += 6.0;
        }
        // NEW: late-stream, prefer exact drains of tight residuals.
        if progress > 0.7 && post_residual > 0 && post_residual <= item_size + 3 && post_residual >= item_size {
            score -= 6.0;
        }
    }

    // Last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 78.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 17.0;
    }

    // Open-bin pressure.
    let pressure = open_bins_count as f64 * 2.0;

    if bin_residual == bin_capacity {
        // New-bin candidate: gate hard when decent fits exist.
        score += 33.0 + pressure + mean_residual * 0.58;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
        if item_size < 42 && progress > 0.45 {
            score += 72.0;
        }
        if next_item_size > 60 && item_size <= 40 {
            score -= 58.0;
        }
        if fitting_bins_count == 0 {
            score -= 105.0;
        }
        if progress > 0.6 && mean_residual > 30.0 {
            score += 29.0;
        }
        if item_size < bin_capacity / 4 && progress > 0.3 {
            score += 19.0;
        }
        // Fresh-bin chain planning: perfect two-item chain.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if next_item_size > 0 && fresh_post == next_item_size {
            score -= 44.0;
        }
        // Fresh-bin quality gate by fill fraction (slightly stricter).
        let fresh_fill = item_size as f64 / cap;
        if fresh_fill < 0.42 {
            score += (0.42 - fresh_fill) * 112.0;
        } else if fresh_fill > 0.5 {
            score -= (fresh_fill - 0.5) * 46.0;
        }
        // Stranded sliver after opening fresh.
        if fresh_post > 0 && fresh_post < 12 && progress > 0.25 {
            score += 23.0;
        }
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size && fitting_bins_count > 0 {
            score += 16.0;
        }
        // Hostable mid-band fresh residuals.
        if fresh_post >= 20 && fresh_post <= 50 {
            score -= 13.0;
        }
        // Avoid opening fresh bins when open bins can host next item too.
        if fitting_bins_count >= 3 {
            score += 12.0 + fitting_bins_count.min(8) as f64 * 1.5;
        }
        // Late-stream consolidation.
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Open fresh only when fresh residual would host the next item well.
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_post > 0 && fresh_post >= next_item_size {
            let slack = fresh_post - next_item_size;
            if slack == 0 {
                score -= 24.0;
            } else if slack <= 6 {
                score -= 16.0;
            } else {
                score += slack.min(40) as f64 * 0.38;
            }
        }
        // Two-step fresh-bin planning.
        if next_item_size > 0 && fresh_post >= next_item_size {
            let after_next = fresh_post - next_item_size;
            if after_next > 0 && after_next <= 6 {
                score -= 11.0;
            }
        }
        // Discourage fresh bins whose residual lands just below the next item.
        if next_item_size > 0 && fresh_post > 0 && fresh_post < next_item_size
            && next_item_size - fresh_post <= 15 {
            score += 13.0;
        }
        // NEW: fresh bins that would strand a sliver below the mean residual
        // are charged a dead-space tax.
        if fresh_post > 0 && fresh_post < 14 {
            score += (14 - fresh_post) as f64 * (1.0 + progress);
        }
    } else {
        score -= pressure * 0.5;
        if next_item_size > 0 && fitting_bins_count > 1 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
        if fitting_bins_count > 2 && post_residual > 0 && post_residual < 30 {
            score -= 4.0;
        }
        // Protect bins whose post-residual can host a large next item.
        if next_item_size > 55 && post_residual >= next_item_size {
            score -= 11.0;
        }
        if post_residual == 0 && next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0;
        }
        // NEW: reward bins that will be emptied exactly (post_residual == 0)
        // more aggressively late in the stream.
        if post_residual == 0 && progress > 0.4 {
            score -= 9.0 * progress;
        }
    }

    // Tight-fit and below-mean-residual preferences.
    score += (bin_residual as f64 - item_size as f64) * 0.12;
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Mid-gap harmony staging zone.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and integer division tiers.
    let pr = post_residual;
    let tier = pr / 10; // coarse tier of dead space
    let class = pr % 10; // fine harmonic class

    // Reward small post_residual strongly (near-perfect packing).
    score -= 12.0 * ((10.0f64).powf(-(tier as f64) * 0.35));

    // Exact fit is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Fine class bonus: residuals divisible by common item granularities (5, 10, 20, 25)
    // are more reusable by future items.
    if pr > 0 {
        if class == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 2.5; } // odd non-round residuals are dead space
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next fits, but measure leftover quality of the chain
            let chain_left = pr - next_item_size;
            if chain_left % 10 == 0 { score -= 8.0; }
            else if chain_left < 10 { score += 3.0; } // creates tiny unusable sliver
            score -= 2.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 4.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; relax late in stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score += 18.0 - 6.0 * progress - 0.5 * pressure.min(20.0);
        // Attractive if mean residual of open bins is small (they're all tight).
        score -= (mean_residual / cap).min(1.0) * 10.0;
        // Very attractive if current item is large (hard to place later).
        if item_size > 60 { score -= 8.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing in fresh bin
        }
    } else {
        // Prefer tighter existing bins slightly when several fit.
        if fitting_bins_count > 1 {
            score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        }
        // Penalize leaving residual in the awkward 1..9 band (unusable slivers).
        if pr >= 1 && pr < 10 {
            score += 5.0;
        }
    }

    score
}

