        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are heavily penalized.
    // Treat residual < 10 as "dead" (smallest item size), with a smooth ramp for near-dead gaps.
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0; // unusable sliver: big penalty
        } else if post_residual <= 20 {
            // small but usable gap: mild penalty so tight fits win
            score += (20.0 - post_residual as f64) * 1.5;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward exact match with the lookahead item (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is a near-miss for next item (wastes future fit)
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones over new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or item is small
        score += 20.0 + pressure * 2.0 + (100.0 - item_size as f64).min(50.0) * 0.3;
        // Exception: opening a fresh bin is fine if no open bin leaves a decent gap
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Slight bonus for placing into bins with below-average residual (balance loads)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
