    score += (bin_residual as f64 - item_size as f64) * 0.12;
    score += (mean_residual - bin_residual as f64) * 0.06;

    // Mid-gap harmony staging zone.
    if post_residual >= 16 && post_residual < 30 && next_item_size > 0
        && post_residual >= next_item_size && next_item_size > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong subtraction when the bin is nearly filled.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Exponential penalty for tiny leftover dead space (unusable residuals).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 200.0 * (1.0 - pr / 10.0);
        }
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            // Next item fits: reward proportionally to how snugly it fits.
            score -= 300.0 * (nr / pr);
            // Bonus if the next item perfectly consumes the remainder.
            if (pr - nr) < 1.0 {
                score -= 250.0;
            }
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful but not zero (wasted space).
            let waste = pr / bin_capacity as f64;
            score += 120.0 * waste;
        }
    } else {
        // Last item: prefer fullest packing, no lookahead needed.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; prefer them (lower score) to consolidate packing.
    let residual_f = bin_residual as f64;
    let dev = residual_f - mean_residual;
    score -= 0.8 * dev;

    // Last-chance bin: if this is the ONLY bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could still consolidate,
    // unless the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit.
        score += 40.0;
        // But if many open bins exist and mean residual is small, opening
        // a fresh bin may be better than fragmenting.
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 90.0;
        }
    }

    // Progress coupling: early in the stream, be more conservative about
    // opening bins; late in the stream, prefer tight closures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
