    // Perfect fit reward: strong subtraction when the bin is nearly filled.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Wasted-space penalty: residuals too small for the average item are dead weight.
        let dead_threshold = (item_size as f64).min(next_item_size as f64).max(1.0);
        if pr < dead_threshold {
            score -= 260.0 * (1.0 - pr / dead_threshold);
        }
        // Extra: residual smaller than half the item is nearly useless.
        if pr * 2.0 < item_size as f64 && pr >= dead_threshold {
            score += 35.0;
        }
