    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            score -= 320.0 * (nr / pr);
            if (pr - nr) < 1.0 {
                score -= 280.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // space is stranded, scaled by how much of the stream remains.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let waste = pr / cap;
            score += (100.0 + 80.0 * (1.0 - progress)) * waste;
        }
    } else {
        score -= 60.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let residual_f = bin_residual as f64;
    let dev = residual_f - mean_residual;
    score -= 0.9 * dev;

    // Last-chance bin: only bin that fits — keep the item out of a fresh bin
    // unless the leftover after placement would be a stranded sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 || post_residual as f64 >= next_item_size as f64 {
            score -= 180.0;
        } else {
            score -= 40.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Fragmentation risk: if mean residual can't hold the item, opening
        // a fresh bin beats forcing a bad fit into a crowded bin.
        if mean_residual < item_size as f64 {
            score -= 110.0;
        }
        // With many open bins, a fresh bin is cheap insurance against
        // scattering small items across many partial bins.
        if open_bins_count > 6 {
            score -= 45.0;
        }
        // Small items early: better to fill existing gaps than spawn bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 25 && progress < 0.5 {
            score += 70.0;
        }
    }

    // Global progress: late stream favors tight closures slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.18 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

