    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // many options: mildly penalize to encourage spreading decisions
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Encourage filling bins that deviate below the mean residual (balance-aware)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late in the stream: consolidate, avoid opening new bins
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // New empty bin candidate: it's attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so open bins win by default
        score += 20.0;
