    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (favor consolidation); later, penalize waste.
    let coupling = norm_pr * norm_pr * (1.0 + progress) * cap;
    score += 0.35 * coupling;

    // Smooth interaction: small post-residual rewarded more as stream progresses
    let tight_bonus = (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress) * cap;
    score -= 0.6 * tight_bonus;

    // Penalize bins far from mean residual (outlier dead space), scaled by progress
    let dev = (pr - mean_residual).abs() / cap;
    score += 20.0 * dev * dev * (0.3 + 0.7 * progress);

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize mildly when open bins exist and fit is fine;
    // reward opening a new bin when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if fitting_bins_count > 0 {
            (bin_residual.saturating_sub(item_size)) as f64
        } else {
            0.0
        };
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 10.0 * openness * (0.4 + 0.6 * (1.0 - progress));
        // lookahead: if next item fits well in the fresh residual, favor new bin
        if next_item_size > 0 {
            let next_fit = if next_item_size <= post_residual {
                (post_residual - next_item_size) as f64 / cap
            } else {
                1.0
            };
            score -= 30.0 * (1.0 - next_fit) * (1.0 - next_fit);
        }
        let _ = waste_elsewhere;
    }

    // Lookahead synergy: if the next item exactly fills this bin's post-residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit closure: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward (kept from parent, sharpened).
        let tightness = 1.0 - pr / cap;
        score -= 45.0 * tightness * tightness;

        // Stranded dead space: residuals too small to hold anything useful.
        if pr < 12.0 {
            score -= 240.0 * (1.0 - pr / 12.0);
        }
        if pr < mean_residual.min(item) * 0.6 {
            score += 60.0 * (1.0 - pr / (mean_residual.min(item) * 0.6));
        }

        // Dead-space ratio coupling: stranded fraction below mean.
        let dead_ratio = pr / cap;
        let mr_ratio = (mean_residual / cap).max(0.01);
        if dead_ratio > 0.015 && dead_ratio < mr_ratio * 0.45 {
            score += 55.0 * dead_ratio / mr_ratio;
        }

        // Snug lookahead fit with graded chain anticipation (combined form).
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            if pr < nr {
                score += 10.0 * (nr - pr);
            } else if pr == nr {
                score -= 300.0;
            } else {
                // Non-linear snugness: reward next-item fit proportional to (nr/pr)^1.4,
                // strongest when the post-fit leftover is minimal.
                let snug = (nr / pr).powf(1.4);
                let chain = if pr < nr * 1.4 { 1.0 - (pr - nr) / (nr * 0.4) } else { 0.0 };
                score -= 300.0 * snug * (0.55 + 0.45 * chain);
                // Two-step chain: leftover after next item could hold another.
                let after = pr - nr;
                if after >= nr * 0.9 && after < mean_residual * 1.2 {
                    score -= 75.0;
                }
                if pr >= nr * 1.4 {
                    // Next item won't fit snugly: penalize stranded fraction.
                    score += 100.0 * (pr / cap);
                    if nr > 0.7 * cap && pr < 0.15 * cap {
                        score -= 110.0;
                    }
                }
            }
        } else {
            score -= 45.0;
        }

        // Graded snugness around the item itself.
        if pr >= item && pr < item * 1.5 {
            score -= 45.0 * (1.0 - (pr - item) / (item * 0.5));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 170.0;
    }

    // Fragmentation pressure: many open bins with small residuals.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.4 * pressure;

    // Relative-to-mean coupling: consolidate toward tighter bins.
    score -= 0.9 * (bin_residual as f64 - mean_residual);

    // Late-stream: prefer minimal post_residual more aggressively.
    score += progress * pr * 0.35;

    // New empty bin candidate.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Open fresh bin when open bins hold scattered residuals the item can't use.
        if open_bins_count > 4 && mean_residual < item {
            score -= 100.0;
