        if progress > 0.6 {
            score += 80.0 * (progress - 0.6) / 0.4;
        }
        // No open bin can fit: new bin is effectively required.
        if fitting_bins_count == 0 {
            score -= 210.0;
        }
        // Large next item and poor current residuals: fresh bin preserves space.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 60.0;
        }
