        if next_item_size > 0 && next_item_size >= item_size as u32 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Progress coupling: early conservative, late prefer tight closures.
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonic" (multiples of common item sizes / quarter classes)
    // are more reusable, so reward them (subtract).
    let quarter = bin_capacity / 4; // 25
    let residue_mod = post_residual % quarter;

    // Perfect harmonic alignment (0 mod 25) is highly reusable.
    if post_residual > 0 && residue_mod == 0 {
        score -= 12.0;
    } else {
        // Penalize dead space proportional to distance from harmonic class boundary.
        let dist_to_boundary = residue_mod.min(quarter - residue_mod) as f64;
        score += dist_to_boundary * 0.35;
    }

    // Integer-division threshold: residual small enough to be "dead" (below min item size)
    if post_residual < 10 {
        score -= 6.0; // effectively full, good placement
    } else if post_residual <= 20 {
        score -= 3.0; // tight, likely to be filled by small items
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_res = post_residual - next_item_size;
            // harmonic chain: next residual also harmonic -> reward
            if next_res % quarter == 0 || next_res < 10 {
                score -= 10.0;
            } else {
                score += (next_res % quarter) as f64 * 0.2;
            }
        } else {
            // next item won't fit here; slight penalty for stranding residual
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when current bins would leave bad harmonic classes.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 18.0;
        // more attractive early in stream or when open bins are already tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    } else {
        // Reward filling existing bins proportionally to how full they get.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
    }

    // Mild pressure against bin proliferation when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

