    if next_item_size > 0 {
        if next_item_size == post {
            score -= 400.0;
        } else if next_item_size <= post {
            // next item fits: reward proportional to tightness
            score -= 50.0 * (1.0 - (post - next_item_size) as f64 / base);
        } else {
            // next item does not fit: mildly penalize large leftover
            score += 10.0 * ((post as f64 - next_item_size as f64).abs() / base);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: keep new bins slightly penalized unless open bins are bad fits
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        // but if mean residual is small (open bins nearly full), opening a new bin is fine
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Tight fit reward relative to capacity
    score -= 20.0 * (1.0 - (post as f64 / base));

    // Stream progression: prefer tighter packing early, more consolidation later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post as f64 / base);

    // Prefer bins with below-mean residual (keeps big gaps concentrated)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit reward: strong subtraction when the bin is fully closed.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Exponential penalty for tiny leftover dead space (unusable residuals).
        // Tightened boundary: residuals below ~10 are almost never reusable.
        if pr < 10.0 {
            score -= 260.0 * (1.0 - pr / 10.0);
        }
        // Penalize residuals that are dead space: too small for the average
        // remaining item, but not zero. Pushes packing toward closures.
        if pr < mean_residual.min(item) * 0.6 {
            score += 60.0 * (1.0 - pr / (mean_residual.min(item) * 0.6));
        }
        // Dead-space ratio coupling — a residual that is a large fraction
        // of the bin but too small for typical items is stranded capacity.
        // Refined: sharpen the boundary so near-mean residuals are spared.
        let dead_ratio = pr / cap;
        let mr_ratio = (mean_residual / cap).max(0.01);
        if dead_ratio > 0.015 && dead_ratio < mr_ratio * 0.45 {
            score += 60.0 * dead_ratio / mr_ratio;
        }
        // Graded snugness — residual just above the item size is the
        // most valuable packing state; reward it proportionally.
        if pr >= item && pr < item * 1.5 {
            score -= 50.0 * (1.0 - (pr - item) / (item * 0.5));
        }
        // New: reusable-space bonus. If post_residual can still hold the
        // mean remaining item with room to spare, this bin stays valuable.
        if mean_residual > 0.0 && pr >= mean_residual * 1.3 {
            score -= 18.0 * ((pr / (mean_residual * 1.3)) - 1.0).min(1.5);
        }
    }

    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= pr {
            // Snugness reward, sharpened non-linearly.
            score -= 340.0 * (nr / pr).powf(1.4);
            if pr - nr < 1.0 {
                score -= 280.0;
            }
            // Two-step chain fit — if the item after next could also
            // squeeze in after the next item, this bin is highly valuable.
            let after = pr - nr;
            if after >= nr * 0.9 && after < mean_residual * 1.2 {
                score -= 85.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted
            // fraction, but only if the leftover is truly stranded.
            let waste = pr / cap;
            score += 140.0 * waste;
            // If the next item is huge and this bin would be nearly full,
            // closing it now is still attractive.
            if nr > 0.7 * cap && pr < 0.15 * cap {
                score -= 110.0;
            }
            // New: if the next item can't fit here AND no other open bin
            // can take the current item either, this is a forced placement —
            // mild reward to avoid pushing the item to a fresh bin.
            if fitting_bins_count == 1 && pr < item * 1.2 {
                score -= 45.0;
            }
        }
    } else {
        score -= 50.0;
    }

    // Relative-to-mean coupling: prefer tight bins to consolidate packing.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.9 * dev;

    // Last-chance bin: avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 170.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Open a fresh bin when open bins have small scattered residuals
        // that the item can't usefully consume anyway.
        if open_bins_count > 4 && mean_residual < item {
            score -= 100.0;
        }
        // Late-stream consolidation: opening new bins late wastes capacity,
        // penalize harder as progress advances.
        if progress > 0.6 {
            score += 75.0 * (progress - 0.6) / 0.4;
        }
        // If no open bin leaves a residual >= item, a new bin is required
        // in spirit; reward it so we don't fragment a decent bin.
        if fitting_bins_count == 0 {
            score -= 210.0;
        }
        // When the next item is large and current open residuals are
        // all below it, opening a clean bin preserves usable space.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 60.0;
        }
        // Early-stream freshness bonus — opening bins early when the
        // stream is long keeps future items from fragmenting half-full bins.
        if progress < 0.25 && open_bins_count < 6 {
            score -= 35.0;
        }
        // New: when several bins already fit the item, a fresh bin is only
        // attractive if the best fit is loose; scale the penalty with the
        // number of alternatives to reduce needless bin sprawl.
        if fitting_bins_count >= 3 {
            score += 55.0 + 12.0 * (fitting_bins_count.min(8) as f64 - 3.0);
        }
    }

    // Progress coupling: early conservative, late prefer tight closures.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 8.0; // worst for gaps of 1..9
    } else if pr == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward filling a bin deeply (large fraction of capacity consumed).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 40.0;

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    } else {
        // New-bin candidate: only attractive when no decent fit exists.
        let avg_gap = if fitting_bins_count > 0 { mean_residual / fitting_bins_count as f64 } else { mean_residual };
        let slack = (bin_residual - item_size) as f64;
        if slack < 10.0 || (avg_gap > item_size as f64 * 1.5 && fitting_bins_count <= 2) {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: favor residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for bins already below average residual (closer to closing).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    score
}

