            score -= 3.0 * (1.0 - slack / cap).powi(2);
        } else {
            // Next item won't fit; penalize proportionally to overshoot, smoothly.
            let over = (nxt - pr) / cap;
            score += 4.0 * over * over * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into existing bins (mild, smooth).
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * norm_pr;

    // Deviation from mean residual: reward bins that keep residual near/below mean.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make an empty bin attractive only when the item is large
    // or when no tight option exists; penalize opening bins for small items late.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 8.0 * (1.0 - fill) * (0.5 + progress);
        if fitting_bins_count > 0 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit closure: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward (quadratic in fill fraction).
        let tightness = 1.0 - pr / cap;
        score -= 45.0 * tightness * tightness;

        // Stranded dead space: residuals too small to hold anything useful.
        if pr < 12.0 {
            score -= 240.0 * (1.0 - pr / 12.0);
        }
        if pr < mean_residual.min(item) * 0.6 {
            score += 60.0 * (1.0 - pr / (mean_residual.min(item) * 0.6));
        }

        // Dead-space ratio coupling: residual large fraction of bin but
        // below a useful threshold is stranded capacity.
        let dead_ratio = pr / cap;
        let mr_ratio = (mean_residual / cap).max(0.01);
        if dead_ratio > 0.015 && dead_ratio < mr_ratio * 0.45 {
            score += 55.0 * dead_ratio / mr_ratio;
        }

        // Graded snugness: residual just above item size is most valuable.
        if pr >= item && pr < item * 1.5 {
            score -= 45.0 * (1.0 - (pr - item) / (item * 0.5));
        }

        // Lookahead: reward when next item fits into post_residual.
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            if pr < nr {
                score += 10.0 * (nr - pr);
            } else if pr == nr {
                score -= 280.0;
            } else if pr < nr * 1.4 {
                score -= 130.0 * (1.0 - (pr - nr) / (nr * 0.4));
            } else {
                // Non-linear snugness reward for next item fitting well.
                score -= 340.0 * (nr / pr).powf(1.4);
                // Two-step chain fit: after next item, room for another.
                let after = pr - nr;
                if after >= nr * 0.9 && after < mean_residual * 1.2 {
                    score -= 80.0;
                }
                // Next item won't fit: penalize stranded fraction.
                score += 140.0 * (pr / cap);
                if nr > 0.7 * cap && pr < 0.15 * cap {
                    score -= 110.0;
                }
            }
        } else {
            score -= 45.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 170.0;
    }

    // Fragmentation pressure: many open bins with small residuals.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.4 * pressure;

    // Relative-to-mean coupling: consolidate toward tighter bins.
    score -= 0.9 * (bin_residual as f64 - mean_residual);

    // Late-stream: prefer minimal post_residual more aggressively.
    score += progress * pr * 0.3;

    // New empty bin candidate.
    if bin_residual == bin_capacity {
        score += 42.0;
        // Open fresh bin when open bins hold scattered residuals the item can't use.
        if open_bins_count > 4 && mean_residual < item {
            score -= 100.0;
        }
        // Late-stream consolidation: opening bins late wastes capacity.
        if progress > 0.6 {
            score += 80.0 * (progress - 0.6) / 0.4;
        }
        // No open bin can fit: new bin is effectively required.
        if fitting_bins_count == 0 {
            score -= 210.0;
        }
        // Large next item and poor current residuals: fresh bin preserves space.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 60.0;
        }
        // Early-stream freshness: keep half-full bins from being fragmented early.
        if progress < 0.25 && open_bins_count < 6 {
            score -= 35.0;
        }
        // Chain enablement: fresh bin leaves room for the next item.
        if next_item_size > 0 && next_item_size >= item_size as u32 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

