        // could still be packed; fewer usable slots => penalize.
        let usable_slots = post_residual / 10;
        score -= (usable_slots.min(9)) as f64 * 8.0;

        // Modulo-based harmonic class: residuals near multiples of common item
        // sizes (10, 20, 25, 50) are more likely to be filled later.
        let pr = post_residual;
        let harmonic_bonus: f64 = if pr % 10 == 0 {
            12.0
        } else if pr % 25 == 0 {
            9.0
        } else if pr % 20 == 0 {
            7.0
        } else if pr % 50 == 0 {
            10.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Lookahead: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size <= pr {
                // next item fits: leave harmonic-compatible room
                if (pr - next_item_size) % 10 == 0 {
                    score -= 30.0;
                } else {
                    score -= 10.0;
                }
            } else {
                // next item won't fit here: mild penalty for wasting lookahead
                score += 15.0;
            }
        }
    }

    // Fraction of capacity wasted
    score += (post_residual as f64 / cap) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
