    }
    // Tiny residues (1..=10) are near-perfect fits: strong reward.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 18.0;
    }
    // Mid-class residues (11..=25) are semi-usable; mild reward.
    if post_residual >= 11 && post_residual <= 25 {
        score -= 6.0;
    }
    // Awkward dead-space band (26..=49): too big to ignore, too small to be
    // reliably reusable -> penalize via non-linear quadratic coupling.
    if post_residual >= 26 && post_residual <= 49 {
        score += 0.02 * (post_residual as f64 - 25.0) * (post_residual as f64 - 25.0);
    }

    // --- Integer-division threshold: can the next item slot into the residue? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead chains nicely: reward proportional to how well it nests.
            score -= 10.0 + 0.2 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item cannot use the residue: penalize the stranded gap.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: we can afford to be picky; slightly raise all scores
    // so the tightest fit (already lowest) dominates by contrast.
    if fitting_bins_count > 2 {
        score += 3.0;
    }

    // --- Mean-residual coupling: prefer bins whose residue is below the mean
    //     (draining fuller bins keeps the bin set homogeneous) ---
    score += 0.08 * (post_residual as f64 - mean_residual);

    // --- New-bin candidate (brand-new empty bin) ---
    if bin_residual == bin_capacity {
        // Base cost: the space left after placing the item, plus opening overhead.
        score = (bin_capacity - item_size) as f64 + 8.0;
        // If NO open bin can fit the item, opening a new bin is forced/best.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is huge, a fresh bin with room is valuable.
        if next_item_size > 60 && item_size <= 40 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items as f64;
        score += 6.0 * progress;
    }

