    // Perfect fit reward: strong subtraction when the bin is fully closed.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Exponential penalty for tiny leftover dead space (unusable residuals).
        if pr < 12.0 {
            score -= 240.0 * (1.0 - pr / 12.0);
        }
        // Penalize residuals that are dead space: too small for the average
        // remaining item, but not zero. Pushes packing toward closures.
        if pr < mean_residual.min(item) * 0.6 {
            score += 60.0 * (1.0 - pr / (mean_residual.min(item) * 0.6));
        }
        // Dead-space ratio coupling — a residual that is a large fraction
        // of the bin but too small for typical items is stranded capacity.
        let dead_ratio = pr / cap;
        let mr_ratio = (mean_residual / cap).max(0.01);
        if dead_ratio > 0.015 && dead_ratio < mr_ratio * 0.45 {
            score += 55.0 * dead_ratio / mr_ratio;
        }
        // Graded snugness — residual just above the item size is the
        // most valuable packing state; reward it proportionally.
        if pr >= item && pr < item * 1.5 {
            score -= 45.0 * (1.0 - (pr - item) / (item * 0.5));
        }
        // New: stranded-space refinement — residuals that cannot host the
        // next item AND are far below mean residual are pure waste; penalize
        // super-linearly so such bins lose priority to better fits.
