            score += 90.0 * (1.0 - pr / mean_residual.max(1.0));
        }
        // New: reward residuals that are exact multiples-ish of the next
        // item, enabling chained placements without dead slivers.
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            let k = (pr / nr).floor();
