    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 170.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Open a fresh bin when open bins have small scattered residuals
        // that the item can't usefully consume anyway.
        if open_bins_count > 4 && mean_residual < item {
            score -= 100.0;
        }
        // Late-stream consolidation: opening new bins late wastes capacity,
        // penalize harder as progress advances.
